/** Local service contracts. Descriptors stay local; only their metadata is registered. */
import type { BusPriority } from '../bus/bus-types.js';
import type { CommandKey, MoveReceipt } from '../../network/generated/galaxy/v1/galaxy_pb.js';
import type { PlayerCommand } from '../../network/session-contracts.js';
import type { FleetSpawnedPayload, FleetsSpawnedBatchPayload, FleetStatePayload, FleetRemovedPayload,
  GenerateFleetPayload, GenerateFleetsBulkPayload } from '../../features/fleets/contracts.js';

export type ServiceKind = 'command' | 'query' | 'event' | 'stream';
export type { CausalContext } from '../../contracts/causal-context.js';
export type ServiceIdentity = Readonly<{ service: string; instance: string; scope: string; source: string }>;
export type ContractMetadata = Readonly<{ id: string; kind: ServiceKind; priority: BusPriority;
  ordered?: string; capacity: number; summary: string }>;
declare const contractTypes: unique symbol;
export interface ServiceContract<K extends ServiceKind, Input, Output = void> extends ContractMetadata {
  readonly kind: K;
  readonly bytes?: (value: Readonly<Input>) => number | undefined;
  readonly [contractTypes]?: (input: Input, output: Output) => [Input, Output];
}
/** Erased registration shape; retain each concrete descriptor in binding inference. */
export type AnyContract = ContractMetadata & { readonly bytes?: (value: never) => number | undefined };
export type ContractInput<C> = C extends ServiceContract<ServiceKind, infer I, any> ? I : never;
export type ContractOutput<C> = C extends ServiceContract<ServiceKind, any, infer O> ? O : never;
type ContractOptions<I> = Partial<Pick<ContractMetadata, 'priority' | 'ordered' | 'capacity' | 'summary'>> & {
  bytes?: (value: Readonly<I>) => number | undefined;
};
function descriptor<K extends ServiceKind, I, O>(kind: K, id: string, options: ContractOptions<I>): ServiceContract<K, I, O> {
  const capacity = options.capacity ?? 128;
  const summary = options.summary ?? 'none';
  validateDescriptor(id, capacity, summary);
  return { id, kind, priority: options.priority ?? 1, capacity, summary,
    ordered: options.ordered, bytes: options.bytes };
}
function validateDescriptor(id: string, capacity: number, summary: string): void {
  if (!id || id.length > 128) throw new Error('Service contract requires a bounded ID');
  if (!Number.isSafeInteger(capacity) || capacity < 1 || capacity > 1024) throw new Error('Invalid service capacity');
  if (summary.length > 128) throw new Error('Service summary policy must be bounded');
}
export const defineCommand = <I, O>(id: string, options: ContractOptions<I> = {}) => descriptor<'command', I, O>('command', id, options);
export const defineQuery = <I, O>(id: string, options: ContractOptions<I> = {}) => descriptor<'query', I, O>('query', id, options);
export const defineEvent = <I>(id: string, options: ContractOptions<I> = {}) => descriptor<'event', I, void>('event', id, options);
/** Stream descriptors register ownership only. Payloads use their direct port and credit protocol. */
export const defineStream = (id: string) => descriptor<'stream', never, never>('stream', id, {});

export type FleetMoveIntent = Readonly<{ commandId: string; fleetId: string;
  target: Readonly<{ x: number; z: number }>; expectedSystemRevision?: bigint }>;
export type FleetTransferIntent = FleetMoveIntent & Readonly<{ destinationSystemId: string }>;
export const FleetOrders = {
  move: defineCommand<FleetMoveIntent, MoveReceipt>('fleetOrders.move', { ordered: 'fleetOrders', capacity: 128 }),
  transfer: defineCommand<FleetTransferIntent, MoveReceipt>('fleetOrders.transfer', { ordered: 'fleetOrders', capacity: 128 }),
  retry: defineCommand<PlayerCommand, MoveReceipt>('fleetOrders.retry', { ordered: 'fleetOrders', capacity: 128 }),
  receipt: defineQuery<CommandKey, MoveReceipt>('fleetOrders.receipt'),
} as const;
export const FleetProjection = { batches: defineStream('fleetProjection.batches') } as const;
export const FleetServices = {
  generate: defineCommand<GenerateFleetPayload, void>('fleets.generate', { ordered: 'fleets' }),
  generateBulk: defineCommand<GenerateFleetsBulkPayload, void>('fleets.generateBulk', { ordered: 'fleets' }),
  spawned: defineEvent<FleetSpawnedPayload>('fleets.spawned', { ordered: 'fleets' }),
  batch: defineEvent<FleetsSpawnedBatchPayload>('fleets.batch', { ordered: 'fleets' }),
  state: defineEvent<FleetStatePayload>('fleets.state', { ordered: 'fleets' }),
  removed: defineEvent<FleetRemovedPayload>('fleets.removed', { ordered: 'fleets' }),
} as const;
