/** Player views cross the service boundary as bounded product data, never wire DTOs. */
import { defineCommand, defineQuery, defineEvent } from '../../worker/protocol/services.js';
export type PlayerViewSlot = 'overview' | 'owned' | 'detail';
export type PlayerViewSelector = { kind:'overview'; scope:{kind:'galaxy'} | {kind:'systems';ids:readonly string[]} | {kind:'clusters';ids:readonly string[]} }
  | {kind:'owned'} | {kind:'detail';systemId:string};
export type PlayerViewToken = Readonly<{ connection:number; request:bigint; baseline:bigint; epoch:bigint; sequence:bigint }>;
export type PlayerViewStatus = Readonly<{slot:PlayerViewSlot;requested?:PlayerViewSelector;requestedGeneration:bigint;displayed?:PlayerViewToken;state:'closed'|'loading'|'ready'|'rejected'|'unavailable';stale:boolean}>;
export type OwnedLocation = {kind:'resident';systemId:string;moving:boolean;arrivalMs?:bigint} | {kind:'transit';sourceSystemId:string;destinationSystemId:string;arrivalMs:bigint};
export type OwnedRosterFleet = Readonly<{id:string;revision:bigint;location:OwnedLocation;sourceRevision:bigint;committedMs:bigint;availability:number}>;
export type OwnedRosterQuery = Readonly<{fleetId?:string;offset?:number;limit?:number;required?:PlayerViewToken}>;
export type OwnedRosterPage = Readonly<{token:PlayerViewToken;fleets:readonly OwnedRosterFleet[];unavailableSourceIds:readonly string[];nextOffset:number|null;total:number}>;
export const PlayerViews = {
  replace:defineCommand<{slot:PlayerViewSlot;selector?:PlayerViewSelector},PlayerViewStatus>('playerViews.replace',{capacity:8,ordered:'playerViewControls'}),
  status:defineQuery<PlayerViewSlot,PlayerViewStatus>('playerViews.status',{capacity:8}),
  owned:defineQuery<OwnedRosterQuery,OwnedRosterPage>('playerViews.owned',{capacity:4}),
  changed:defineEvent<PlayerViewStatus>('playerViews.changed',{capacity:16,ordered:'playerViewEvents'}),
} as const;
