import { validateViewRequest } from './views/validate.js';
import type { ClientHello, ClientMessage, MoveCommand, SubscribeSystem, TransferCommand } from "./generated/galaxy/v1/galaxy_pb.js";
import { check, cursor, id, key, position, scope, token } from "./validate-fields.js";
import { validateSubscribeStrategic } from './validate-strategic.js';

function hello(value: ClientHello): void {
  check(value.minimumProtocolVersion > 0 && value.minimumProtocolVersion <= 1 && value.maximumProtocolVersion >= 1, "protocol version range");
  check(value.supportedRuleVersions.length <= 16 && value.supportedRuleVersions.includes(1), "rule versions");
  check(value.requiredCapabilities.length <= 16, "capabilities length");
  for (const capability of value.requiredCapabilities) check(capability >= 1 && capability <= 11, "required capability");
  token(value.sessionCredential);
}

function move(value: MoveCommand): void {
  key(value.key);
  scope(value.scope);
  id(value.fleetId);
  position(value.target);
  token(value.admissionToken);
  if (value.expectedSystemRevision !== undefined) {
    check(value.expectedSystemRevision >= 0n && value.expectedSystemRevision <= 0xffffffffffffffffn, "expected revision");
  }
}

function subscribe(value: SubscribeSystem): void {
  id(value.worldId);
  id(value.systemId);
  id(value.subscriptionId);
  if (!value.resumeAfter) return;
  cursor(value.resumeAfter);
  check(value.subscriptionId.every((byte, index) => value.resumeAfter?.subscriptionId[index] === byte), "resume subscription");
}

function transfer(value: TransferCommand): void {
  key(value.key); scope(value.scope); id(value.fleetId); id(value.destinationSystemId);
  position(value.destinationPosition); token(value.admissionToken);
  if (value.expectedSystemRevision !== undefined) {
    check(value.expectedSystemRevision >= 0n && value.expectedSystemRevision <= 0xffffffffffffffffn, "expected revision");
  }
}

export function validateClientMessage(message: ClientMessage): void {
  const body = message.body;
  if (body.case === "hello") {
    check(message.protocolVersion === 0 && message.connectionGeneration === 0n, "hello envelope");
    hello(body.value);
    return;
  }
  check(message.protocolVersion === 1 && message.connectionGeneration > 0n, "session envelope");
  switch (body.case) {
    case "viewRequest": validateViewRequest(body.value); break;
    case "move": move(body.value); break;
    case "transfer": transfer(body.value); break;
    case "receiptQuery": id(body.value.worldId); key(body.value.key); break;
    case "renewAdmission": if(body.value.systemId.length){id(body.value.systemId);check(!body.value.receiptHomeShardId.length,"renewal selector");}else id(body.value.receiptHomeShardId); check(body.value.requestId > 0n, "renewal request identity"); break;
    case "playbackClock": scope(body.value.scope); cursor(body.value.baseline);
      check(body.value.requestId > 0n && body.value.systemRevision > 0n, "playback request"); break;
    case "subscribe": subscribe(body.value); break;
    case "subscribeStrategic": validateSubscribeStrategic(body.value); break;
    default: throw new Error("Client message has no supported operation");
  }
}
