import { create } from '@bufbuild/protobuf';
import { ClientMessageSchema, MoveCommandSchema, TransferCommandSchema, type AdmissionGrant, type AuthorityScope, type ClientMessage,
  type MoveCommand, type StreamCursor, type TransferCommand } from './generated/galaxy/v1/galaxy_pb.js';
import { opaqueIdBytes, opaqueIdAt } from '../contracts/opaque-id.js';
import type { NetworkControl, SystemSubscription } from './session-contracts.js';

export function hello(credential: Uint8Array, options: {
  discovery?: boolean; ownedProjection?: boolean; transfers?: boolean; diagnostics?: boolean; renewAdmissions?: boolean; strategic?: boolean;
} = {}): ClientMessage {
  if (credential.byteLength !== 32) throw new Error('Provisioned session credential must contain 32 bytes');
  return create(ClientMessageSchema, { body: { case: 'hello', value: {
    minimumProtocolVersion: 1, maximumProtocolVersion: 1, supportedRuleVersions: [1],
    requiredCapabilities: [1, 2, ...(options.discovery ? [3 as const] : []), ...(options.ownedProjection ? [4 as const] : []),
      ...(options.transfers ? [5 as const] : []), ...(options.diagnostics ? [6 as const] : []), ...(options.renewAdmissions ? [7 as const] : []),
      ...(options.strategic ? [8 as const] : [])], sessionCredential: credential,
  } } });
}
export function clientMessage(generation: bigint, body: ClientMessage['body']): ClientMessage {
  return create(ClientMessageSchema, { protocolVersion: 1, connectionGeneration: generation, body });
}
export function subscribeMessage(generation: bigint, subscription: SystemSubscription, resumeAfter?: StreamCursor): ClientMessage {
  return create(ClientMessageSchema, { protocolVersion: 1, connectionGeneration: generation, body: { case: 'subscribe', value: {
    worldId: opaqueIdBytes(subscription.worldId), systemId: opaqueIdBytes(subscription.systemId),
    subscriptionId: opaqueIdBytes(subscription.subscriptionId), resumeAfter,
  } } });
}
export function moveCommand(control: Extract<NetworkControl, { type: 'move' }>, scope: AuthorityScope, admissions: AdmissionGrant[], serverNow: bigint): MoveCommand {
  const grant = admission(scope, admissions, serverNow);
  return create(MoveCommandSchema, {
    key: { commandId: opaqueIdBytes(control.commandId), receiptHomeShardId: grant.receiptHomeShardId, admissionGeneration: grant.generation },
    scope, fleetId: opaqueIdBytes(control.fleetId), target: control.target,
    expectedSystemRevision: control.expectedSystemRevision, admissionToken: grant.token,
  });
}
export function transferCommand(control: Extract<NetworkControl, { type: 'transfer' }>, scope: AuthorityScope, admissions: AdmissionGrant[], serverNow: bigint): TransferCommand {
  const grant = admission(scope, admissions, serverNow);
  return create(TransferCommandSchema, {
    key: { commandId: opaqueIdBytes(control.commandId), receiptHomeShardId: grant.receiptHomeShardId, admissionGeneration: grant.generation },
    scope, fleetId: opaqueIdBytes(control.fleetId), destinationSystemId: opaqueIdBytes(control.destinationSystemId), destinationPosition: control.target,
    expectedSystemRevision: control.expectedSystemRevision, admissionToken: grant.token,
  });
}
function admission(scope: AuthorityScope, admissions: AdmissionGrant[], serverNow: bigint): AdmissionGrant {
  const grant = admissions.find(item => opaqueIdAt(item.receiptHomeShardId) === opaqueIdAt(scope.shardId) && item.notAfterServerMs >= serverNow);
  if (!grant) throw new Error('No current command admission grant for this receipt home');
  return grant;
}
