/** Reconnect carries intent only. Every restored selector needs fresh authorization. */
import { isOpaqueId } from '../../contracts/opaque-id.js';
import type { PlayerViewSelector, PlayerViewSlot } from './service-contracts.js';
type Selection = Partial<Record<PlayerViewSlot,PlayerViewSelector|null>>;
export type ViewInterests = {world:string;player:string;slots:Selection;accepted?:Selection};
function copySelection(source:Selection):Selection {
  const result:Selection={};
  for(const slot of names){const value=source[slot];if(value!==undefined)result[slot]=value===null?null:normalizedSelector(value);}
  return result;
}
const names=['overview','owned','detail'] as const;
export function normalizedSelector(value:PlayerViewSelector):PlayerViewSelector {
  if(value.kind==='owned')return {kind:'owned'};
  if(value.kind==='detail'){
    if(!isOpaqueId(value.systemId))throw new Error('Invalid detail identity');
    return {kind:'detail',systemId:value.systemId};
  }
  if(value.scope.kind==='galaxy')return {kind:'overview',scope:{kind:'galaxy'}};
  if(value.scope.ids.length>4096||!value.scope.ids.every(isOpaqueId))throw new Error('Invalid overview membership');
  return {kind:'overview',scope:{kind:value.scope.kind,ids:[...new Set(value.scope.ids)].sort()}};
}
export function createViewInterests(world:string,player:string,initial?:ViewInterests){
  const selected:ViewInterests['slots']={},accepted:ViewInterests['slots']={};
  const generations=new Map<PlayerViewSlot,bigint>();
  if(initial?.world===world&&initial.player===player){
    Object.assign(selected,copySelection(initial.slots));Object.assign(accepted,copySelection(initial.accepted??{}));
  }
  function snapshot():ViewInterests {
    return {world,player,slots:copySelection(selected),accepted:copySelection(accepted)};
  }
  return {snapshot,
    request(slot:PlayerViewSlot,generation:bigint,value?:PlayerViewSelector){
      if(value&&value.kind!==slot)throw new Error('Wrong interest slot');
      generations.set(slot,generation);selected[slot]=value?normalizedSelector(value):null;
      if(!value)accepted[slot]=null;
    },
    accept(slot:PlayerViewSlot,generation:bigint){if(generations.get(slot)===generation)accepted[slot]=selected[slot];},
    reject(slot:PlayerViewSlot,generation:bigint){if(generations.get(slot)===generation){if(accepted[slot]===undefined)delete selected[slot];else selected[slot]=accepted[slot];}},
  };
}
